mapper.select:
SELECT A.OZR_SIGN, B.APLPR_ID, B.APLPR_NM, B.SIGN_DATA1,B.SIGN_DATA2,B.SIGN_DATA3,B.SIGN_DATA4,B.SIGN_DATA5,B.SIGN_DATA6,B.SIGN_DATA7,B.SIGN_DATA8,B.SIGN_DATA9,B.SIGN_DATA10, B.FM_APRV_DT FROM (SELECT '/upload/sign.ozr' OZR_SIGN, 1 AS SEQ FROM DUAL A) A, (SELECT 1 SEQ, APLPR_ID, APLPR_NM, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,1) AS SIGN_DATA1, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,4001) AS SIGN_DATA2, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,8001) AS SIGN_DATA3, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,12001) AS SIGN_DATA4, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,16001) AS SIGN_DATA5, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,20001) AS SIGN_DATA6, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,24001) AS SIGN_DATA7, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,28001) AS SIGN_DATA8, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,30001) AS SIGN_DATA9, dbms_lob.substr(APLPR_SSIGN_IMG_INR_QRY_CTT,4000,32001) AS SIGN_DATA10, TO_CHAR(APRV_DT, 'YYYY-MM-DD') AS FM_APRV_DT FROM GE_MP_APLPRSGN_S WHERE 1 = 1
AND PPCD = #{PPCD}
AND APLPR_ID = #{SH_APLPR_ID}
) B WHERE A.SEQ = B.SEQ (+)

	SELECT count(*)
	  FROM (SELECT  '/upload/sign.ozr' OZR_SIGN, 1 AS SEQ FROM DUAL A) A, 
	  	   (SELECT 1 SEQ, APLPR_ID, APLPR_NM FROM GE_MP_APLPRSGN_S
	  	   WHERE 1 = 1

      		 AND PPCD = #{PPCD}


      		 AND APLPR_ID = #{SH_APLPR_ID}

      	   ) B
  WHERE A.SEQ = B.SEQ (+)
